        .create(
            new SszPublicKey(depositRequest.getPubkey()),
            SszBytes32.of(depositRequest.getWithdrawalCredentials()),
            SszUInt64.of(depositRequest.getAmount()),
            new SszSignature(depositRequest.getSignature()),
            SszUInt64.of(state.getSlot()));
    pendingDeposits.append(deposit);
  }
}"""

VALIDATE_PAYLOAD_HEADER_EXCERPT = """// PRIMARY: ethereum/spec/.../BlockProcessorBellatrix.java:validateExecutionPayloadHeader (lines 177-202)
public void validateExecutionPayloadHeader(
    final BeaconState genericState, final ExecutionPayloadHeader executionPayloadHeader)
    throws BlockProcessingException {
  final BeaconStateBellatrix state = BeaconStateBellatrix.required(genericState);
  if (miscHelpersBellatrix.isMergeTransitionComplete(state)) {
    if (!executionPayloadHeader.getParentHash()
        .equals(state.getLatestExecutionPayloadHeader().getBlockHash())) {
      throw new BlockProcessingException(
          "Execution payload parent hash does not match previous execution payload header");
    }
  }
  if (!beaconStateAccessors.getRandaoMix(state, beaconStateAccessors.getCurrentEpoch(state))
      .equals(executionPayloadHeader.getPrevRandao())) {
    throw new BlockProcessingException("Execution payload randao does not match state randao");
  }
  if (!miscHelpersBellatrix.computeTimeAtSlot(state.getGenesisTime(), state.getSlot())
      .equals(executionPayloadHeader.getTimestamp())) {
    throw new BlockProcessingException("Execution payload timestamp does not match time for state slot");
  }
}"""

